    public static str dopackItems2Image(Set _items)
    {
        if(!_items || !_items.elements())
        {
            return '';
        }
        str ret;
        real counter = roundUp(sqrt(_items.elements()),1);
        int i;
        Map         sizemap = new Map(Types::String, Types::String);
        Map         imageMap = new Map(Types::String, Types::Class);
        Map         rects = new Map(Types::String,Types::Class);
        Map         orders = new Map(Types::String, Types::String);
        SetEnumerator sEnum = _items.getEnumerator();
        MapEnumerator   mEnum;
        MapEnumerator   rectEnum;

        System.Drawing.Image    itemImage;

        DocuRef docuRef;
        int imgDim = real2int(1000.0 / counter);

        //Greedy placement from large to small.
        //Put the largest rectangle remaining into your packed area. If it can't fit anywhere, place it in a place that extends the pack region as little as possible.
        //Repeat until you finish with the smallest rectangle.

        while (sEnum.moveNext())
        {
            docuRef = TFMHelper::findDefaultImageDocuRef(InventTable::find(sEnum.current()));
            if (!docuRef)
            {
                itemImage = TFMImageHelper::base64ToImage(TFMImageHelper::resource2Base64(resourceStr(TFMMissingImage)));
            }
            else
            {
                itemImage = TFMHelper::getAttachmentAsImage(docuRef);
            }
            if(itemImage)
            {
                itemImage = TFMImageHelper::scaleImage(itemImage,imgDim*2,imgDim);
                sizemap.insert(int2Str(1000000 - itemImage.Width * itemImage.Height) + sEnum.current(),sEnum.current());
                imageMap.insert(sEnum.current(), itemImage);
                i++;
            }
        }
        i = 0;
        mEnum = sizemap.getEnumerator();
        while (mEnum.moveNext())
        {
            orders.insert(mEnum.currentValue(),int2Str(i));
            i++;
            //Each Image, Largest first
            itemImage = imageMap.lookup(mEnum.currentValue());
            int x = 0, y = 0;
            int extraWidth = 4000;//, extraHeight = 4000;
            //int totalWidth = 4000, totalHeight = 4000;
            //int extraArea = 400000000;
            System.Drawing.Rectangle rect = new System.Drawing.Rectangle(0,0,itemImage.Width,itemImage.Height);
            System.Drawing.Rectangle totalRect = TFMDocGetMedia::totalRect(rects.getEnumerator());
            rectEnum = rects.getEnumerator();            
            while (rectEnum.moveNext())
            {
                //placement, place to the right and below each existing rect. Evaluate which placement is best, save that.
                System.Drawing.Rectangle existingRect = rectEnum.currentValue();

                //Try right
                rect.X = existingRect.X + existingRect.Width +2 ;
                rect.Y = existingRect.Y;
                if (!TFMDocGetMedia::intersectionTest(rects.getEnumerator(), rect))
                { 
                    if (extraWidth > rect.Right)
                    {
                        extraWidth = rect.Right;
                        x = rect.X;
                        y = rect.Y;
                    }
                }
            }
            if (extraWidth < totalRect.Height + itemImage.Height || i == _items.elements())
            {
                rect.X = x;
                rect.Y = y;
            }
            else
            {
                rect.X = 0;
                rect.Y = totalRect.Bottom + 2;
            }
            rects.insert(mEnum.currentValue(),rect);
        }
        System.Int32 width = 0;//TFMDocGetMedia::totalRect(rects.getEnumerator()).Width;
        System.Int32 height= 0;//TFMDocGetMedia::totalRect(rects.getEnumerator()).Height;
        mEnum = rects.getEnumerator();
        while (mEnum.moveNext())
        {
            System.Drawing.Rectangle elRect = mEnum.currentValue();
            width = max(width, elRect.X + elRect.Width);
            height= max(height, elRect.Y + elRect.Height);

        }
        i = 0;

        System.Drawing.Image    image =  new System.Drawing.Bitmap(width,height);// new System.Drawing.Bitmap(TFMDocGetMedia::totalRect(rects.getEnumerator()).Width,TFMDocGetMedia::totalRect(rects.getEnumerator()).Height);
        System.Drawing.Graphics Graphics =  System.Drawing.Graphics::FromImage(image);
        mEnum = rects.getEnumerator();
        while (mEnum.moveNext())
        {
            itemImage = imageMap.lookup(mEnum.currentKey());
            System.Drawing.Rectangle rect = mEnum.currentValue();
            Graphics.DrawImage(itemImage,rect);
			if (true)
            {
				continue;
            }
            Graphics.DrawLine(new System.Drawing.Pen(System.Drawing.Color::Black),rect.X,rect.Y,rect.Right,rect.Y);
            Graphics.DrawLine(new System.Drawing.Pen(System.Drawing.Color::Black),rect.Right,rect.Y,rect.Right,rect.Bottom);
            Graphics.DrawLine(new System.Drawing.Pen(System.Drawing.Color::Black),rect.Right,rect.Bottom,rect.X,rect.Bottom);
            Graphics.DrawLine(new System.Drawing.Pen(System.Drawing.Color::Black),rect.X,rect.Bottom,rect.X,rect.Y);
            Graphics.DrawString(orders.lookup(mEnum.currentKey()) + ' ' +int2Str(rect.Right) + 'x' + int2Str(rect.Bottom),new System.Drawing.Font('Segoe Script',15),new System.Drawing.SolidBrush(System.Drawing.Color::White),rect.X-1,rect.Y-1);
            Graphics.DrawString(orders.lookup(mEnum.currentKey()) + ' ' +int2Str(rect.Right) + 'x' + int2Str(rect.Bottom),new System.Drawing.Font('Segoe Script',15),new System.Drawing.SolidBrush(System.Drawing.Color::White),rect.X+1,rect.Y+1);
            Graphics.DrawString(orders.lookup(mEnum.currentKey()) + ' ' +int2Str(rect.Right) + 'x' + int2Str(rect.Bottom),new System.Drawing.Font('Segoe Script',15),new System.Drawing.SolidBrush(System.Drawing.Color::Black),rect.X,rect.Y);

                i++;
        }

        ret = TFMImageHelper::Image2Base64(image);
        return ret;
    }

private static System.Drawing.Rectangle totalRect(MapEnumerator _rects)
{
    System.Drawing.Rectangle retRect = new System.Drawing.Rectangle(0,0,1,1);
    while (_rects.moveNext())
    {
        System.Drawing.Rectangle rect = _rects.currentValue();
        retRect.Width = max(retRect.Width, rect.X + rect.Width);
        retRect.Height= max(retRect.Height, rect.Y + rect.Height);
    }

    return retRect;
}

private static boolean intersectionTest(MapEnumerator _rects, System.Drawing.Rectangle _rect)
{        
    boolean intersects = false;
    while (_rects.moveNext() && !intersects)
    {
        //Check intersection with each placement.
        System.Drawing.Rectangle intersectRectangle = System.Drawing.Rectangle::Intersect(_rect, _rects.currentValue());
        intersects = intersects || !intersectRectangle.IsEmpty;
    }
    if (intersects)
    {
        //No Good placement
        return intersects;
    }
    return intersects;
}

private void GetMedia()
{
    XmlElement              mediaNode = request.parmOrigXML().root().getNamedElement(TFMConstants::requestData()).getNamedElement('mediaIds').firstChild();
    Map                     mediaMap = new Map(Types::String, Types::String);

    while (mediaNode)
    {
        iconRequested = mediaNode.innerText();
        mediaMap.insert(mediaNode.innerText(),TFMDocGetMedia::getBase64FromName(mediaNode.innerText(), request));
        mediaNode = mediaNode.nextSibling();
    }

    this.createResponse(mediaMap);
}

