    public static str getBase64FromName(str _nameOfImage, TFMRequestElement _request = null)
    {
        TFMParameters           parms;
        TFMImageTable           imgTable;
        DocuRef                 docuRef;
        InventItemBarcode       inventItemBarcode;
        ItemId                  itemId;
        InventDim               inventDimLookup;
        InventItemGTIN          inventItemGTIN;
        System.Drawing.Image    image;
        System.Drawing.Image    newImage;
        int						folderPos;
        TFMImageAggregate		imgAggr;
        str                     base64Img;
        boolean                 createFrame = false;
        str                     imageName = _nameOfImage;

        TFMMediaProvider mediaProvider = TFMMediaProvider::instance();
        base64Img = mediaProvider.getBase64ForMedia(_nameOfImage);
        if(base64Img)
        {
            return base64Img;
        }

        docuRef = TFMHelper::findImageDocuRef(imgTable,parms.DocuTypeId);

        if (!docuRef)
        {
            docuRef = docuRef::findRecId(str2Int64(subStr(_nameOfImage,1,strScan(_nameOfImage,'_',1,100))));
            createFrame = parms.ImageFrames;
        }

        if (!docuRef)
        {
            imgTable = TFMImageTable::Find(_nameOfImage);
            if(imgTable)
            {
                base64Img = TFMImageHelper::Image2Base64(TFMHelper::getAttachmentAsImage(TFMHelper::findImageDocuRef(imgTable)));
                if(base64Img)
                {
                    TFMMediaProvider::instance().setMedia(_nameOfImage, base64Img, null);
                    return base64Img;
                }
            }
        }

        if (!docuRef && imageName)
        {
            // not a folder but verify if the imageName exists and create the base 64.
            str classImage = TFMDocGetMedia::doesClassHaveImage(imageName);
            base64Img = TFMImageHelper::resource2Base64(classImage ? classImage : imageName);
            if(base64Img)
            {
                TFMMediaProvider::instance().setMedia(_nameOfImage, base64Img, null);
                return base64Img;
            }
        }
        if (!docuRef)
        {
            //Check if item id or barcode (pinpoint)
            inventItemBarcode = InventItemBarcode::findInputBarcode(_nameOfImage);
            if (inventItemBarcode)
            {
                itemId = inventItemBarcode.itemId;
                inventDimLookup = inventItemBarcode.inventDim();
            }
            else
            {
                inventItemGTIN = InventItemGTIN::findGTIN(_nameOfImage);
                if (inventItemGTIN)
                {
                    itemId = inventItemGTIN.itemId;
                    inventDimLookup = inventDim::find(inventItemGTIN.inventDimId);
                }
                else if (InventTable::exist(_nameOfImage))
                {
                    itemId = InventTable::find(_nameOfImage).ItemId;
                }
            }
            docuRef = TFMHelper::FindItemDocuref(itemId,inventDimLookup.inventDimId);
        }



		if (!docuRef)
        {
            base64Img = TFMDocGetMedia::findImageFromImageHandlerClasses(_nameOfImage);
			if (base64Img)
            {
                TFMMediaProvider::instance().setMedia(_nameOfImage, base64Img, null);
                return base64Img;
            }
        }

        if (!docuRef && strScan(_nameOfImage,',',1,strLen(_nameOfImage)))
        {
            List itemList = strSplit(_nameOfImage,',');
            Set itemSet = new Set(Types::String);
            ListEnumerator lEnum = itemList.getEnumerator();
            while(lEnum.moveNext())
            {
                itemSet.add(lEnum.current());
            }
            return TFMDocGetMedia::dopackItems2Image(itemSet);

        }

		if (!docuRef)
        {
            imgAggr = TFMImageAggregate::Find(_nameOfImage); // Migrate to image handler class
			if(imgAggr)
            {
                return imgAggr.getImage();
            }
        }
        if (!docuRef && _nameOfImage && SysResource::checkIfResourceExists(_nameOfImage) && SysResource::getResourceNodeType(SysResource::getResourceNode(_nameOfImage)) == SysResourceType::Image)
        {
            return TFMImageHelper::resource2Base64(_nameOfImage);
        }

        if (!docuRef)
        {
            return TFMImageHelper::resource2Base64(resourceStr(TFMMissingImage));
        }
        image = TFMImageHelper::ExifRotateImage(TFMHelper::getAttachmentAsImage(docuRef));

        if (!image)
        {
            return TFMImageHelper::resource2Base64(resourceStr(TFMMissingImage));
        }

        newImage = TFMImageHelper::scaleImage(image,1000,1000);
        if ( createFrame)
        {
            newImage = TFMImageHelper::frameImage(newImage);
        }
        //var props = image.PropertyItems;
        if (image.PropertyIdList.Contains(274))
        {
            newImage.SetPropertyItem(image.GetPropertyItem(274));
        }
        base64Img = TFMImageHelper::Image2Base64(newImage);
        return base64Img;
    }

    private static str findImageFromImageHandlerClasses(str _imageId)
    {
        SysDictClass		dc = new SysDictClass(classNum(TFMImageHandler));
        TFMImageHandler		imageHandler;
        str					result = '';
        ListEnumerator subClss = dc.extendedBy(true).getEnumerator();

		while ( subClss.moveNext())
        {
            imageHandler = new SysDictClass(subClss.current()).makeObject();

            result = imageHandler.process(_imageId);
			if (result)
            {
                return result;
            }

        }
        return result;
    }

/// <summary>
/// Go through the TFMDocumentHandlers to get a map of registered images. 
/// </summary>
/// <returns>a map of string as a key value that points to a resourceStr (the value).</returns>
public static Map classImages()
{
    DictClass           dc = new DictClass(className2Id(classStr(TFMDocumentHandler)));
    DictClass           subClass;
    List                extendingClasses = dc.extendedBy(true);
    ListEnumerator      lEnum = extendingClasses.getEnumerator();
    TFMDocumentHandler  docHand;
    Map					returnMap = new Map(Types::String, Types::String);
    MapEnumerator		mEnum;
    Map                 imageSet;

    while (lEnum.moveNext())
    {
        subClass = new DictClass(lEnum.current());
        if (subClass == null || subClass.isAbstract())
        {
            continue;
        }
        docHand = subClass.makeObject() as TFMDocumentHandler;
        imageSet = docHand.registerImage();
        mEnum = imageSet.getEnumerator();
        while (mEnum.moveNext())
        {
            returnMap.insert(mEnum.currentKey(), mEnum.currentValue());
        }
    }
    return returnMap;
}

public static str doesClassHaveImage(str _imageID)
{        
    Map       imageSet = TFMDocGetmedia::classImages();

    if ( imageSet.exists(_imageID))
    {
        return imageSet.lookup(_imageID);
    }

    return '';
}

private void createResponse(Map _medias)
{
    MapEnumerator       mEnum = _medias.getEnumerator();
    XmlElement          ordersElement;
    XmlElement             nodeCreated;

    resultXml   = new XmlDocument();

    ordersElement = resultXml.appendChild(resultXml.createElement('media'));

    while (mEnum.moveNext())
    {
        nodeCreated = resultXml.createElement('image');
        nodeCreated.setAttribute('id',mEnum.currentKey());
        nodeCreated.text(mEnum.currentValue());
        ordersElement.appendChild(nodeCreated);
    }
}

private static str base64ToURL(str _base64, str _fileName)
{
    FileUploadTemporaryStorageStrategy fileUploadStrategy = new FileUploadTemporaryStorageStrategy();
    System.IO.Stream Stream = new System.IO.MemoryStream(System.Convert::FromBase64String(_base64));
    FileUploadTemporaryStorageResult fileUploadResult = fileUploadStrategy.uploadFile(Stream, _fileName + '.png');
    return fileUploadResult.getDownloadUrl();
}

public static str getURLFromIconName(str _iconName, boolean allowBase64Value = true)
{
    TFMMediaProvider mediaProvider = TFMMediaProvider::instance();
    TFMMediaItem mediaItem = mediaProvider.getMedia(_iconName);
    str path;
    if(mediaItem)
    {
        // only allow if the caller can retrieve a base64 or the URL is present.
        if(allowBase64Value || mediaItem.parmURL())
        {
            return mediaItem.getMediaForHtml();
        }
    }

    str resourceName	= TFMDocGetMedia::doesClassHaveImage(_iconName);
    str base64;
    if (resourceName && SysResource::checkIfResourceExists(resourceName))
    {
        path = SysResource::getImagePath(resourceName);
        mediaProvider.setMedia(_iconName, null, path);
        return path;
    }

    if(!_iconName)
    {
        return TFMDocGetMedia::getURLFromIconName(resourceStr(TFMMissingImage));
    }

    if (SysResource::checkIfResourceExists(_iconName))
    {
        path = SysResource::getImagePath(_iconName);
        mediaProvider.setMedia(_iconName, null, path);
        return path;
    }
    base64			= TFMDocGetMedia::getBase64FromName(_iconName);

    if(allowBase64Value)
    {
        mediaProvider.setMedia(_iconName, base64, null);
        return mediaProvider.getMedia(_iconName).getMediaForHtml();
    }

    return TFMDocGetMedia::base64ToURL(base64, _iconName);
}
